solution:
const original = { a: 1, b: 2, c: 3 }
const entries = Object.entries(original)
const doubled = entries.map(([k, v]) => [k, v * 2])
const rebuilt = Object.fromEntries(doubled)
return {
  entries: entries,
  doubled: rebuilt
}
